const watchPrompt=p=>{if(!p.promptSeen)p.promptSeen=new Promise(r=>p.on('dialog',d=>{if(d.type()!=='prompt')return;p.handedOver=true;p.bringToFront().catch(()=>{});r(d.message())}));return p.promptSeen};
